#!/bin/bash
# Blocks agent writes to secrets, generated files and dependencies. Needs jq.
set -uo pipefail

command -v jq >/dev/null || { echo "jq is required by the guard hooks (brew install jq)" >&2; exit 2; }

FILE_PATH=$(jq -r '.tool_input.file_path // .tool_input.filePath // empty')
[ -z "$FILE_PATH" ] && exit 0
BASENAME=$(basename "$FILE_PATH")

if echo "$BASENAME" | grep -qE '^\.env($|\.)'; then
  echo "Protected file: $FILE_PATH (.env*) must not be edited by an agent" >&2
  exit 2
fi

if echo "$FILE_PATH" | grep -qE '(^|/)(vendor|var|\.git|config/jwt|\.phpunit\.cache)/'; then
  echo "Protected path: $FILE_PATH (vendor, var, .git, config/jwt) must not be edited by an agent" >&2
  exit 2
fi

if [ "$BASENAME" = "composer.lock" ] || [ "$BASENAME" = "symfony.lock" ]; then
  echo "Protected file: $FILE_PATH is generated by composer; run composer instead" >&2
  exit 2
fi

exit 0
